import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)

DB_PATH = os.environ.get('DB_PATH', '/tmp/app.db')
ADMIN_TOKEN = os.environ.get('ADMIN_TOKEN', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        password_hash TEXT NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    pw_hash = hashlib.sha256(b'admin:supersecret').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, email, role, password_hash) VALUES (?, ?, ?, ?)",
               ('admin', 'admin@internal.corp', 'admin', pw_hash))
    db.execute("INSERT OR IGNORE INTO users (username, email, role, password_hash) VALUES (?, ?, ?, ?)",
               ('alice', 'alice@example.com', 'user', hashlib.sha256(b'alice:password123').hexdigest()))
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by username or email. Supports partial matching."""
    query = request.args.get('q', '')
    field = request.args.get('field', 'username')

    # Basic input validation - only allow alphanumeric and common chars
    # NOTE: this is intentionally insufficient
    if len(query) > 100:
        return jsonify({'error': 'Query too long'}), 400

    # Log the search for audit purposes
    db = get_db()
    db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
               ('search', f'field={field}, q={query}'))
    db.commit()

    # Build query - field is validated against allowlist
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        field = 'username'

    # Vulnerable: query parameter is interpolated directly
    sql = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{query}%'"

    try:
        results = db.execute(sql).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    db = get_db()
    user = db.execute("SELECT id, username, email, role FROM users WHERE id = ?", (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/admin/export', methods=['POST'])
def export_data():
    """Admin endpoint to export user data. Requires admin token."""
    token = request.headers.get('X-Admin-Token', '')
    if token != ADMIN_TOKEN:
        return jsonify({'error': 'Unauthorized'}), 403

    fmt = request.json.get('format', 'json') if request.json else 'json'
    db = get_db()
    users = db.execute("SELECT id, username, email, role FROM users").fetchall()

    if fmt == 'csv':
        import csv
        import io
        output = io.StringIO()
        writer = csv.writer(output)
        writer.writerow(['id', 'username', 'email', 'role'])
        for u in users:
            writer.writerow([u['id'], u['username'], u['email'], u['role']])
        return output.getvalue(), 200, {'Content-Type': 'text/csv'}

    return jsonify({'users': [dict(u) for u in users]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    debug_mode = os.environ.get('FLASK_DEBUG', '0') == '1'
    app.run(host='0.0.0.0', port=8080, debug=debug_mode)
